// titleFor/statuteTextFor: real translation where curated (hi/te), else honest English.
// Placeholders NEVER get a fake language prefix.
export function titleFor(statute, lang = 'en') {
    const l = (lang || 'en').toLowerCase();
    if ((l === 'hi' || l === 'te') && statute && STATUTE_I18N[statute.id]?.[l]?.title) {
        return STATUTE_I18N[statute.id][l].title;
    }
    return statute?.title || '';
}

export function statuteTextFor(statute, lang = 'en') {
    const l = (lang || 'en').toLowerCase();
    if ((l === 'hi' || l === 'te') && statute && STATUTE_I18N[statute.id]?.[l]?.text) {
        return STATUTE_I18N[statute.id][l].text;
    }
    return statute?.text || '';
}
